using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new ResearchTools();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(tools.SearchWeb),
        AIFunctionFactory.Create(tools.TakeNote),
        AIFunctionFactory.Create(tools.GetNotes),
    ],
};

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Given a topic, you:
        1. Search the web multiple times with varied queries to gather broad information.
        2. Take notes on the key findings from each search.
        3. After gathering enough information (at least 3 searches), retrieve your
           notes and produce a concise, well-structured summary with the key points.
        Always cite where information came from when possible.
        """),
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("── Research Summary ─────────────────────────────");
Console.WriteLine(response.Text);
Console.WriteLine("─────────────────────────────────────────────────");

if (tools.NoteCount > 0)
{
    Console.WriteLine($"\n📝 {tools.NoteCount} note(s) were taken during research.");
}

// ── Helpers ──────────────────────────────────────────────────────────────────

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? throw new InvalidOperationException("A research topic is required.")
        : input;
}

// ── Tools ────────────────────────────────────────────────────────────────────

public sealed class ResearchTools
{
    private readonly List<(string Topic, string Content)> _notes = [];
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } },
    };

    public int NoteCount => _notes.Count;

    [Description("Search the web for information. Returns relevant snippets and related topics.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&t=ResearchAgent";
            var json = await Http.GetStringAsync(url);

            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;
            var sb = new StringBuilder();

            // Abstract (instant answer)
            var abs = root.GetProperty("Abstract").GetString();
            if (!string.IsNullOrWhiteSpace(abs))
            {
                var src = root.GetProperty("AbstractSource").GetString();
                sb.AppendLine($"Summary ({src}): {abs}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var related))
            {
                foreach (var item in related.EnumerateArray().Take(8))
                {
                    if (item.TryGetProperty("Text", out var text))
                        sb.AppendLine($"- {text.GetString()}");
                }
            }

            var result = sb.ToString();
            return string.IsNullOrWhiteSpace(result)
                ? "No detailed results found. Try a different or more specific query."
                : result;
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note capturing a key finding.")]
    public string TakeNote(
        [Description("Short topic label for the note")] string topic,
        [Description("The detailed content of the note")] string content)
    {
        _notes.Add((topic, content));
        Console.WriteLine($"  📝 Note saved: \"{topic}\"");
        return $"Note #{_notes.Count} saved under \"{topic}\".";
    }

    [Description("Retrieve all saved research notes to compile a final summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            var (topic, content) = _notes[i];
            sb.AppendLine($"[Note {i + 1} – {topic}]");
            sb.AppendLine(content);
            sb.AppendLine();
        }

        return sb.ToString();
    }
}

